window.docContents[147].resolve({"/Preface/#Logical-Foundations--Preface--Resources--Lecture-Videos":{"contents":"Lectures for two intensive summer courses based on Logical\nFoundations (part of the DeepSpec summer school series) can be\nfound at <https://deepspec.org/event/dsss17> and\n<https://deepspec.org/event/dsss18/>.  The video quality in the\n2017 lectures is poor at the beginning but gets better in the\nlater lectures.\n\n","context":"Logical Foundations\u0009Preface\u0009Resources","header":"1.4.2. Lecture Videos","id":"/Preface/#Logical-Foundations--Preface--Resources--Lecture-Videos"},"/Tactics/#Logical-Foundations--Tactics___-More-Basic-Tactics--Review":{"contents":"\n\nThis list is getting pretty long; maybe it should be\nfurther divided into catgories (I'd suggest: Basic hypotheses/goal\nmanipulation, equality, indutive types, others)\n\n\n\nMicro SermonMindless proof-hacking is a terrible temptation...Try to resist!\n\n\n\n\n\n\n\n\n\n\n\n","context":"Logical Foundations\u0009Tactics: More Basic Tactics","header":"7.8. Review","id":"/Tactics/#Logical-Foundations--Tactics___-More-Basic-Tactics--Review"}});